#include <stdint.h>

// RCC
#define RCC_BASE     0x40023800UL
#define RCC_AHB1ENR  (*((volatile uint32_t *)(RCC_BASE + 0x30)))

// GPIOD
#define GPIOD_BASE   0x40020C00UL
#define GPIOD_MODER  (*((volatile uint32_t *)(GPIOD_BASE + 0x00)))
#define GPIOD_ODR    (*((volatile uint32_t *)(GPIOD_BASE + 0x14)))

// SysTick（Cortex-M4 內部）
#define SYSTICK_BASE  0xE000E010UL
#define SYSTICK_CTRL  (*((volatile uint32_t *)(SYSTICK_BASE + 0x00)))
#define SYSTICK_LOAD  (*((volatile uint32_t *)(SYSTICK_BASE + 0x04)))
#define SYSTICK_VAL   (*((volatile uint32_t *)(SYSTICK_BASE + 0x08)))

// 全域計數器，每 1ms 加一
volatile uint32_t tick = 0;

// SysTick 中斷 handler（每 1ms 觸發一次）
void SysTick_Handler(void)
{
    tick++;
}

void delay_ms(uint32_t ms)
{
    uint32_t start = tick;
    while ((tick - start) < ms);
}

int main(void)
{
    // 1. 設定 SysTick 每 1ms 中斷一次
    // 系統預設 clock = 16MHz
    // 16000000 / 1000 = 16000 counts per ms
    SYSTICK_LOAD = 16000 - 1;   // reload value
    SYSTICK_VAL  = 0;            // 清除目前值
    SYSTICK_CTRL = 0x7;          // bit0=enable, bit1=tickint, bit2=clksource(內部clock)

    // 2. 開啟 GPIOD clock
    RCC_AHB1ENR |= (1 << 3);

    // 3. PD12 設為 output
    GPIOD_MODER &= ~(0x3 << (12 * 2));
    GPIOD_MODER |=  (0x1 << (12 * 2));

    while (1)
    {
        GPIOD_ODR ^= (1 << 12);
        delay_ms(500);   // 精確 500ms
    }
}
